#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n, b;
    std::cin >> n >> b;
    std::vector<int> data(n);
    std::vector<int> parityValues(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> data[i];
        parityValues[i] = (data[i] % 2 == 0) ? -1 : 1;
    }
    int runningSum = 0;
    std::vector<int> edgeCosts;
    for (int i = 0; i < n - 1; ++i) {
        runningSum += parityValues[i];
        if (runningSum == 0) {
            int diff = std::abs(data[i + 1] - data[i]);
            edgeCosts.push_back(diff);
        }
    }
    std::sort(edgeCosts.begin(), edgeCosts.end());
    int totalCost = 0;
    int maxEdges = 0;
    for (int cost : edgeCosts) {
        if (totalCost + cost <= b) {
            totalCost += cost;
            ++maxEdges;
        }
    }
    std::cout << maxEdges << std::endl;
    return 0;
}

